#include "SimulationShards.hpp"
namespace elysium::simulation {static std::uint32_t key(ShardTier t,ClockFamily c){return(std::uint32_t(t)<<8)|std::uint32_t(c);}void SimulationShardScheduler::setCadence(ShardTier t,ClockFamily c,std::uint64_t v){cadences_[key(t,c)]=std::max<std::uint64_t>(1,v);}std::uint64_t SimulationShardScheduler::cadence(ShardTier t,ClockFamily c)const{auto i=cadences_.find(key(t,c));return i==cadences_.end()?1:i->second;}bool SimulationShardScheduler::upsert(ShardRecord r){if(!r.id)return false;return shards_.insert_or_assign(r.id,r).second;}bool SimulationShardScheduler::requestTier(StableId id,ShardTier target,std::string&w){auto i=shards_.find(id);if(i==shards_.end()){w="unknown shard";return false;}if(std::uint8_t(target)>std::uint8_t(i->second.tier)&&i->second.hasUnsafeReservation){w="unsafe demotion";return false;}i->second.tier=target;++i->second.revision;return true;}void SimulationShardScheduler::enqueueWakeup(Wakeup w){if(!w.shard)return;for(auto&x:wakeups_)if(x.shard==w.shard&&x.type==w.type){x.tick=std::min(x.tick,w.tick);return;}wakeups_.push_back(w);}std::vector<Wakeup> SimulationShardScheduler::dueWakeups(std::uint64_t tick,std::size_t maxCount){std::sort(wakeups_.begin(),wakeups_.end(),[](auto&a,auto&b){return a.tick==b.tick?(a.shard==b.shard?a.type<b.type:a.shard<b.shard):a.tick<b.tick;});std::vector<Wakeup>out;for(auto i=wakeups_.begin();i!=wakeups_.end()&&out.size()<maxCount;){if(i->tick>tick)break;out.push_back(*i);i=wakeups_.erase(i);}return out;}}
